import sys
import math

def orientation(p, q, r):
    val = (q[1] - p[1]) * (r[0] - q[0]) - (q[0] - p[0]) * (r[1] - q[1])
    if val == 0:
        return 0
    return 1 if val > 0 else 2

def on_segment(p, q, r):
    return (q[0] <= max(p[0], r[0]) and q[0] >= min(p[0], r[0]) and
            q[1] <= max(p[1], r[1]) and q[1] >= min(p[1], r[1]))

def do_intersect(p1, q1, p2, q2):
    o1 = orientation(p1, q1, p2)
    o2 = orientation(p1, q1, q2)
    o3 = orientation(p2, q2, p1)
    o4 = orientation(p2, q2, q1)

    if o1 != o2 and o3 != o4:
        return True

    if o1 == 0 and on_segment(p1, p2, q1):
        return True
    if o2 == 0 and on_segment(p1, q2, q1):
        return True
    if o3 == 0 and on_segment(p2, p1, q2):
        return True
    if o4 == 0 and on_segment(p2, q1, q2):
        return True

    return False

def distance(p1, p2):
    return math.sqrt((p1[0] - p2[0]) ** 2 + (p1[1] - p2[1]) ** 2)

def count_fruits_on_line(fruits, p1, p2):
    count = 0
    for fruit in fruits:
        center = (fruit[0], fruit[1])
        if distance(p1, center) <= 1 or distance(p2, center) <= 1:
            count += 1
        elif do_intersect(p1, p2, (center[0] - 1, center[1]), (center[0] + 1, center[1])):
            count += 1
    return count

def max_fruits_sliced(fruits):
    n = len(fruits)
    if n < 2:
        return n

    max_count = 0
    for i in range(n):
        for j in range(i + 1, n):
            p1 = (fruits[i][0], fruits[i][1])
            p2 = (fruits[j][0], fruits[j][1])
            count = count_fruits_on_line(fruits, p1, p2)
            max_count = max(max_count, count)

    return max_count

def main():
